<?php
namespace App\Commands\AiOps; use App\Commands\SafeBaseCommand; use CodeIgniter\CLI\CLI;
class Watch extends SafeBaseCommand { protected $group='AiOps'; protected $name='aiops:watch'; protected $description='Continuous aiops audit watcher'; protected $options=['--interval'=>'Seconds','--max-cycles'=>'0 infinite','--heal'=>'Run self-heal']; public function run(array $params){$this->parseParams($params);$interval=max(30,(int)($this->request->getOption('interval')??900));$max=(int)($this->request->getOption('max-cycles')??0);$heal=(string)($this->request->getOption('heal')??'0')==='1';$i=0; while($max===0 || $i<$max){$i++; CLI::write("[cycle {$i}] ".date('c')); command('aiops:audit --json=1'); if($heal){command('aiops:self-heal --attempts=1 --json=1');} sleep($interval);} return EXIT_SUCCESS; }}
